const blockCommentCloserValueCases = [
  {
    diagram: "eventmodeling",
    fixture: "comment-native",
    mark: "/*",
    label: "block-comment-eventmodeling-c-closer-value",
    report: {
      where: "Comment at 14-30",
      message:
        'value of a native Comment: " multi\\nline */", not " multi\\nline "',
    },
    closer: "*/",
  },
  {
    diagram: "railroad",
    fixture: "ir-c-comment-first-closer",
    mark: "/*",
    label: "block-comment-railroad-c-closer-value",
    report: {
      where: "Comment at 14-34",
      message:
        'value of a native Comment: " outer /* inner */", not " outer /* inner "',
    },
    closer: "*/",
  },
  {
    diagram: "railroad",
    fixture: "ebnf-iso-first-closer",
    mark: "(*",
    label: "block-comment-railroad-iso-closer-value",
    report: {
      where: "Comment at 19-39",
      message:
        'value of a native Comment: " outer (* inner *)", not " outer (* inner "',
    },
    closer: "*)",
  },
] as const

describe("checkTree: native block comment bounds (tokens.md)", () => {
  for (const entry of blockCommentCloserRangeCases) {
    it(`reports ${entry.label}`, () => {
      const { input, tree } = recordedTree(entry.diagram, entry.fixture)
      const broken = copyOf(tree)
      const comment = broken.comments.find((item) => item.mark === entry.mark)!
      span(input, comment, comment.range[0], comment.range[1] - 2)
      expect(checkTree(input, broken)).toContainEqual(entry.report)
    })
  }

  for (const entry of blockCommentOpenerValueCases) {
    it(`reports ${entry.label}`, () => {
      const { input, tree } = recordedTree(entry.diagram, entry.fixture)
      const broken = copyOf(tree)
      const comment = broken.comments.find((item) => item.mark === entry.mark)!
      setField(comment, "value", entry.mark + comment.value)
      expect(checkTree(input, broken)).toContainEqual(entry.report)
    })
  }

  for (const entry of blockCommentCloserValueCases) {
    it(`reports ${entry.label}`, () => {
      const { input, tree } = recordedTree(entry.diagram, entry.fixture)
      const broken = copyOf(tree)
      const comment = broken.comments.find((item) => item.mark === entry.mark)!
      setField(comment, "value", comment.value + entry.closer)
      expect(checkTree(input, broken)).toContainEqual(entry.report)
    })
  }
})

