/** Places a recorded body after one of the two fixed frontmatter inputs. */
function treeWithTokenFrontmatter(
  input: string,
  original: { readonly input: string; readonly tree: CheckedRoot },
  blank: boolean,
): CheckedRoot {
  const shifted = copyOf(original.tree)
  const by = input.length - original.input.length
  for (const placed of [...nodesOf(shifted).slice(1), ...shifted.tokens]) {
    span(input, placed, placed.range[0] + by, placed.range[1] + by)
  }
  const end = blank ? 15 : 40
  const valueRange: readonly [number, number] = [8, blank ? 11 : 36]
  const pieces: [string, { readonly text: string; readonly from: number }][] = [
    ["Punctuator", { text: "---", from: 2 }],
  ]
  if (!blank) pieces.push(["RawText", { text: input.slice(13, 33), from: 13 }])
  pieces.push(["Punctuator", { text: "---", from: end - 3 }])
  const tree = handMadeRoot(input, {
    tokens: pieces,
    frontmatter: frontmatterOf(input, input.slice(2, end), valueRange),
  })
  setField(tree, "diagramType", original.tree.diagramType)
  setField(tree, "body", shifted.body)
  setField(tree, "tokens", [...tree.tokens, ...shifted.tokens])
  return tree
}

for (const testCase of frontmatterTokenCases) {
  it(`fails ${testCase.testCase}`, () => {
    const original = recordedTree(testCase.diagram, testCase.fixture)
    const { input, blankInput } = testCase
    const tree = treeWithTokenFrontmatter(input, original, false)
    const blank = treeWithTokenFrontmatter(blankInput, original, true)
    // packages/parser/docs/tokens.md, Frontmatter tokens: these complete fixed
    // inputs have delimiter-line whitespace, a blank line before the body,
    // body boundary whitespace, and an indented later line; a body may be blank.
    expect(checkTree(input, tree)).toEqual([])
    expect(checkTree(blankInput, blank)).toEqual([])

    /** Checks the token-layout report for one frontmatter mutation. */
    function frontmatterReport(source: string, broken: CheckedRoot): void {
      expect(checkTree(source, broken)).toContainEqual({
        where: "the tokens in the range of the frontmatter",
        message: expect.stringContaining(
          "are not the opening delimiter, the body, and the closing delimiter",
        ),
      })
    }

    const opening = copyOf(tree)
    setField(opening.tokens[0], "type", "RawText")
    frontmatterReport(input, opening)

    const closing = copyOf(tree)
    setField(closing.tokens[2], "type", "RawText")
    frontmatterReport(input, closing)

    const bodyKind = copyOf(tree)
    setField(bodyKind.tokens[1], "type", "Identifier")
    frontmatterReport(input, bodyKind)

    const order = copyOf(tree)
    const reversed = [...order.tokens]
    const first = reversed[0]
    reversed[0] = reversed[1]
    reversed[1] = first
    setField(order, "tokens", reversed)
    frontmatterReport(input, order)

    const firstCharacter = copyOf(tree)
    extendToken(input, firstCharacter.tokens[1], 12, 33)
    frontmatterReport(input, firstCharacter)

    const lastCharacter = copyOf(tree)
    extendToken(input, lastCharacter.tokens[1], 13, 34)
    frontmatterReport(input, lastCharacter)

    const blankBody = copyOf(blank)
    setField(blankBody, "tokens", [
      blankBody.tokens[0],
      tokenOf(blankInput, "RawText", { text: " ", from: 8 }),
      ...blankBody.tokens.slice(1),
    ])
    frontmatterReport(blankInput, blankBody)

    const blankLine = copyOf(tree)
    setField(blankLine, "tokens", [
      blankLine.tokens[0],
      tokenOf(input, "RawText", { text: " ", from: 8 }),
      ...blankLine.tokens.slice(1),
    ])
    frontmatterReport(input, blankLine)

    const firstIndent = copyOf(tree)
    extendToken(input, firstIndent.tokens[1], 10, 33)
    frontmatterReport(input, firstIndent)

    const afterDelimiter = copyOf(tree)
    extendToken(input, afterDelimiter.tokens[2], 37, 41)
    frontmatterReport(input, afterDelimiter)

    const laterIndent = copyOf(tree)
    const originalBody = laterIndent.tokens[1]
    setField(laterIndent, "tokens", [
      laterIndent.tokens[0],
      {
        ...originalBody,
        value: input.slice(13, 22),
        range: [13, 22],
        loc: locationOf(input, [13, 22]),
      },
      {
        ...originalBody,
        value: input.slice(24, 33),
        range: [24, 33],
        loc: locationOf(input, [24, 33]),
      },
      ...laterIndent.tokens.slice(2),
    ])
    frontmatterReport(input, laterIndent)

    const bodyValue = copyOf(tree)
    setField(
      bodyValue.frontmatter!,
      "value",
      bodyValue.frontmatter!.value.replace("  second", "second"),
    )
    expect(checkTree(input, bodyValue)).toContainEqual({
      where: "Frontmatter at 2-40",
      message: expect.stringContaining("value: "),
    })

    const openingLine = copyOf(tree)
    setField(openingLine, "tokens", [
      openingLine.tokens[0],
      tokenOf(input, "RawText", { text: " ", from: 6 }),
      ...openingLine.tokens.slice(1),
    ])
    frontmatterReport(input, openingLine)

    const closingLine = copyOf(tree)
    setField(closingLine, "tokens", [
      ...closingLine.tokens.slice(0, 2),
      tokenOf(input, "RawText", { text: "\t", from: 36 }),
      ...closingLine.tokens.slice(2),
    ])
    frontmatterReport(input, closingLine)

    const lineSeparator = copyOf(tree)
    extendToken(input, lineSeparator.tokens[0], 2, 6)
    frontmatterReport(input, lineSeparator)
  })
}

