/** A fixed graph whose two vertex groups provide the edge named by index 10. */
function multiCharacterAgentflowNumber(): { input: string; tree: CheckedRoot } {
  const input =
    "agentflow-beta TB\nA & B & C & D --> E & F & G\nlinkStyle 10  \n"
  const bodyStart = input.indexOf("\n") + 1

  /** Finds a named vertex in the fixed graph statement. */
  function vertexStart(name: string) {
    return input.indexOf(name, bodyStart)
  }

  const tree = handMadeRoot(input, {
    bodyType: "AgentflowDiagram",
    tokens: [
      ["Keyword", "agentflow-beta"],
      ["Keyword", "TB"],
      ["Identifier", { text: "A", from: bodyStart }],
      ["Punctuator", { text: "&", from: vertexStart("A") + 1 }],
      ["Identifier", { text: "B", from: bodyStart }],
      ["Punctuator", { text: "&", from: vertexStart("B") + 1 }],
      ["Identifier", { text: "C", from: bodyStart }],
      ["Punctuator", { text: "&", from: vertexStart("C") + 1 }],
      ["Identifier", { text: "D", from: bodyStart }],
      ["Punctuator", "-->"],
      ["Identifier", { text: "E", from: bodyStart }],
      ["Punctuator", { text: "&", from: vertexStart("E") + 1 }],
      ["Identifier", { text: "F", from: bodyStart }],
      ["Punctuator", { text: "&", from: vertexStart("F") + 1 }],
      ["Identifier", { text: "G", from: bodyStart }],
      ["Keyword", "linkStyle"],
      ["Numeric", "10"],
    ],
  })

  /** Builds the vertex at its fixed source position. */
  function vertex(name: string) {
    const start = vertexStart(name)
    const range = [start, start + 1] as const
    const loc = locationOf(input, range)
    return {
      type: "AgentflowVertex",
      range,
      loc,
      id: { type: "Identifier", name, range, loc },
      shape: null,
      cssClass: null,
      data: [],
    }
  }

  const firstRange = [vertexStart("A"), vertexStart("D") + 1] as const
  const targetRange = [vertexStart("E"), vertexStart("G") + 1] as const
  const arrowStart = input.indexOf("-->")
  const arrowRange = [arrowStart, arrowStart + 3] as const
  const graphRange = [firstRange[0], targetRange[1]] as const
  const linkRange = [arrowStart, targetRange[1]] as const
  const numberStart = input.indexOf("10")
  const numberRange = [numberStart, numberStart + 2] as const
  const styleRange = [input.indexOf("linkStyle"), numberRange[1]] as const
  setField(tree, "diagramType", "agentflow")
  setField(tree.body, "direction", "TB")
  setField(tree.body, "body", [
    {
      type: "AgentflowVertexStatement",
      range: graphRange,
      loc: locationOf(input, graphRange),
      first: {
        type: "AgentflowVertexGroup",
        vertices: [vertex("A"), vertex("B"), vertex("C"), vertex("D")],
        range: firstRange,
        loc: locationOf(input, firstRange),
      },
      links: [
        {
          type: "AgentflowLink",
          id: null,
          opening: null,
          label: null,
          arrow: {
            type: "AgentflowArrow",
            value: "-->",
            startMarker: "none",
            line: "solid",
            length: 2,
            endMarker: "arrow",
            range: arrowRange,
            loc: locationOf(input, arrowRange),
          },
          target: {
            type: "AgentflowVertexGroup",
            vertices: [vertex("E"), vertex("F"), vertex("G")],
            range: targetRange,
            loc: locationOf(input, targetRange),
          },
          range: linkRange,
          loc: locationOf(input, linkRange),
        },
      ],
    },
    {
      type: "AgentflowLinkStyleStatement",
      range: styleRange,
      loc: locationOf(input, styleRange),
      indices: [
        {
          type: "NumericLiteral",
          value: 10,
          raw: "10",
          range: numberRange,
          loc: locationOf(input, numberRange),
        },
      ],
      interpolate: null,
      styles: [null],
    },
  ])
  return { input, tree }
}

