for (const testCase of directiveGapTokenCases) {
  it(`fails ${testCase.testCase}`, () => {
    const original = recordedTree(testCase.diagram, testCase.fixture)
    const tree = copyOf(original.tree)
    const target = nodesOf(tree)[testCase.node]
    const [start, end] = target.range
    const width = testCase.parts[4][2]
    const delta = width - (end - start)
    const { input } = testCase
    for (const placed of [...nodesOf(tree), ...tree.tokens]) {
      span(
        input,
        placed,
        placed.range[0] >= end ? placed.range[0] + delta : placed.range[0],
        placed.range[1] >= end ? placed.range[1] + delta : placed.range[1],
      )
    }
    span(input, tree, 0, input.length)
    setField(target, testCase.field, testCase.value)
    if (target.type === "StringLiteral") {
      setField(target, "raw", input.slice(start, start + width))
    }
    const item = tree.tokens[testCase.token]
    extendToken(input, item, start, start + width)
    replaceToken(tree, item, testCase.parts)
    setField(
      tree,
      "directives",
      testCase.directives.map((from) =>
        directiveOf(input, { text: "%%{init: {}}%%", from }),
      ),
    )
    const tail = testCase.directives[2]
    setField(tree, "tokens", [
      ...tree.tokens,
      tokenOf(input, "Directive", { text: "%%{init: {}}%%", from: tail }),
    ])
    // packages/parser/docs/tokens.md, A token that a directive cuts: read
    // whitespace between directives remains a token and belongs to the value.
    // A standalone directive follows the body. Treemap has only LF after it,
    // because that diagram permits no unused trailing indentation unit.
    expect(checkTree(input, tree)).toEqual([])

    const missingMiddle = copyOf(tree)
    setField(
      missingMiddle,
      "tokens",
      missingMiddle.tokens.filter((_, index) => index !== testCase.token + 2),
    )
    expect(checkTree(input, missingMiddle)).toContainEqual({
      where: `${target.type} at ${start}-${start + width}`,
      message: testCase.missingReport,
    })

    const wrongDirectiveKind = copyOf(tree)
    setField(wrongDirectiveKind.tokens[testCase.token + 1], "type", "RawText")
    expect(checkTree(input, wrongDirectiveKind)).toContainEqual({
      where: "the Directive tokens",
      message: expect.stringContaining(
        "are not those of the directives outside all other tokens and all comments",
      ),
    })

    const unread = copyOf(tree)
    const gap = tail + "%%{init: {}}%%".length
    setField(unread, "tokens", [
      ...unread.tokens,
      tokenOf(input, "RawText", { text: " ", from: gap }),
    ])
    expect(checkTree(input, unread)).toContainEqual({
      where: `RawText at ${gap}-${gap + 1}`,
      message:
        "starts with whitespace or a line terminator where no value starts",
    })
  })
}

