for (const entry of sharedCommentMissingRecordCases) {
  it(`reports ${entry.id}`, () => {
    const input = entry.input
    const tree = copyOf(recordedTree(entry.diagram, entry.fixture).tree)
    for (const placed of [
      ...nodesOf(tree).filter((node) => node !== tree),
      ...tree.tokens,
    ])
      span(
        input,
        placed,
        placed.range[0] + entry.prefixLength,
        placed.range[1] + entry.prefixLength,
      )
    span(input, tree, 0, input.length)
    setField(tree, "comments", [
      commentOf(input, "%%", {
        text: entry.commentText,
        from: entry.commentFrom,
      }),
    ])
    for (const directive of entry.directives)
      setField(tree, "directives", [directiveOf(input, directive)])
    // packages/parser/docs/tokens.md, Comment: common comment lines and
    // detection-passed bare lines own their marks, ranges and source text;
    // directive scans carry line feeds and exclude their scanned EOF trivia.
    // Ordinary comments keep EOF whitespace that no directive scan takes
    // (packages/spec/docs/common.md, Comment lines).
    expect(checkTree(input, tree)).toEqual([])
    const broken = copyOf(tree)
    setField(broken, "comments", [])
    expect(checkTree(input, broken)).toContainEqual(entry.expected)
  })
}

