    const broken = copyOf(tree)
    const [start, end] = entry.range
    setField(
      broken,
      "tokens",
      broken.tokens.filter(
        (item) => item.range[1] <= start || item.range[0] >= end,
      ),
    )
    setField(broken, "comments", [
      ...broken.comments,
      commentOf(input, "%%", { text: input.slice(start, end), from: start }),
    ])
