it("reports tokens-228-sankey-noncomment-percent-field-is-not-a-Comment", () => {
  const input = "sankey\n%%{!},b,1\nA,B,2\n"
  const tree = handMadeRoot(input, {
    bodyType: "SankeyDiagram",
    tokens: [
      ["Keyword", "sankey"],
      ["RawText", "%%{!}"],
      ["Punctuator", { text: ",", from: 12 }],
      ["RawText", { text: "b", from: 13 }],
      ["Punctuator", { text: ",", from: 14 }],
      ["RawText", { text: "1", from: 15 }],
      ["RawText", { text: "A", from: 17 }],
      ["Punctuator", { text: ",", from: 18 }],
      ["RawText", { text: "B", from: 19 }],
      ["Punctuator", { text: ",", from: 20 }],
      ["RawText", { text: "2", from: 21 }],
    ],
  })
  setField(tree, "diagramType", "sankey")
  setField(tree.body, "body", [
    {
      type: "SankeyLinkStatement",
      source: {
        type: "SankeyIdentifier",
        name: "%%{!}",
        range: [7, 12],
        loc: locationOf(input, [7, 12]),
      },
      target: {
        type: "SankeyIdentifier",
        name: "b",
        range: [13, 14],
        loc: locationOf(input, [13, 14]),
      },
      value: {
        type: "SankeyLiteral",
        value: "1",
        range: [15, 16],
        loc: locationOf(input, [15, 16]),
      },
      range: [7, 16],
      loc: locationOf(input, [7, 16]),
    },
    {
      type: "SankeyLinkStatement",
      source: {
        type: "SankeyIdentifier",
        name: "A",
        range: [17, 18],
        loc: locationOf(input, [17, 18]),
      },
      target: {
        type: "SankeyIdentifier",
        name: "B",
        range: [19, 20],
        loc: locationOf(input, [19, 20]),
      },
      value: {
        type: "SankeyLiteral",
        value: "2",
        range: [21, 22],
        loc: locationOf(input, [21, 22]),
      },
      range: [17, 22],
      loc: locationOf(input, [17, 22]),
    },
  ])
  // packages/spec/docs/diagrams/sankey.md, Comments and the record context,
  // permit percent text in fields and define no diagram comment. The opening
  // %%{!} is no shared directive or comment line (common.md, Comment lines).
  const baseline = checkTree(input, tree)
  const broken = copyOf(tree)
  const statements = broken.body.body
  if (!Array.isArray(statements))
    throw new Error("the diagram has no body list")
  // Retain the second record so the broken tree still has its required body.
  setField(broken.body, "body", statements.slice(1))
  setField(
    broken,
    "tokens",
    broken.tokens.filter((item) => item.range[0] < 7 || item.range[0] >= 17),
  )
  setField(broken, "comments", [
    commentOf(input, "%%", { text: "%%{!},b,1", from: 7 }),
  ])
  const output = checkTree(input, broken)
  expect(baseline).toEqual([])
  expect(output).toContainEqual({
    where: "Comment at 7-16",
    message: "the mark %% is no mark of the comments of a SankeyDiagram",
  })
})

