it.each([
  {
    case: "tokens-extra-real-empty-fragment-hand-eventmodeling",
    diagram: "eventmodeling",
    fixture: "comment-default-size-above-crlf",
    input:
      "eventmodeling\r\ntf 01 evt A [[D]]\r\ndata D {\r\nx\r\n%% \n%% d\r\ny\r\n}\r\n",
    nodeSpans: [
      {
        type: "Root",
        range: [0, 50008],
        span: [0, 50013],
      },
      {
        type: "EventmodelingDiagram",
        range: [0, 50006],
        span: [0, 50011],
      },
      {
        type: "EventmodelingDataEntityStatement",
        range: [34, 50006],
        span: [34, 50011],
      },
      {
        type: "EventmodelingDataBlock",
        range: [41, 50006],
        span: [41, 50011],
      },
      {
        type: "EventmodelingLiteral",
        range: [42, 50005],
        span: [42, 50010],
      },
    ],
    tokenSpans: [
      {
        index: 12,
        span: [50007, 50010],
      },
      {
        index: 13,
        span: [50010, 50011],
      },
    ],
    commentStart: 50001,
    point: 50001,
    index: 12,
    kind: "RawText",
  },
] as const)(
  "reports an empty fragment token between two comment regions in $case",
  (theCase) => {
    // packages/parser/docs/tokens.md, Comment regions in tokens: an empty
    // middle fragment between successive regions has no token.
    const recorded = recordedTree(theCase.diagram, theCase.fixture)
    const input = theCase.input
    const tree = copyOf(recorded.tree)
    const originalTargets = theCase.nodeSpans.map((patch) => ({
      patch,
      node: nodesOf(tree).find(
        (candidate) =>
          candidate.type === patch.type &&
          candidate.range[0] === patch.range[0] &&
          candidate.range[1] === patch.range[1],
      )!,
    }))
    for (const { patch, node } of originalTargets) {
      span(input, node, patch.span[0], patch.span[1])
      if ("raw" in patch) setField(node, "raw", patch.raw)
    }
    for (const patch of theCase.tokenSpans)
      extendToken(input, tree.tokens[patch.index], patch.span[0], patch.span[1])
    setField(tree, "comments", [
      ...tree.comments,
      commentOf(input, "%%", { text: "%% d", from: theCase.commentStart }),
    ])
    expect(checkTree(input, tree)).toEqual([])
    const broken = copyOf(tree)
    const empty = tokenOf(input, theCase.kind, {
      text: "",
      from: theCase.point,
    })
    setField(broken, "tokens", [
      ...broken.tokens.slice(0, theCase.index),
      empty,
      ...broken.tokens.slice(theCase.index),
    ])
    expect(checkTree(input, broken)).toContainEqual({
      where: `${theCase.kind} at ${theCase.point}-${theCase.point}`,
      message: "is empty",
    })
  },
)

