it.each([
  {
    case: "tokens-extra-88-sankey-read-whitespace-after-Comment",
    lines: [88, 358],
    diagram: "sankey",
    fixture: "db-quoted-comment-line",
    input: 'sankey\n"a\n%% c\n b",x,1\n',
    index: 2,
    nodeType: "StringLiteral",
    nodeRange: [7, 17],
    nodeSpans: [
      {
        type: "Root",
        range: [0, 22],
        span: [0, 23],
      },
      {
        type: "SankeyDiagram",
        range: [0, 21],
        span: [0, 22],
      },
      {
        type: "SankeyLinkStatement",
        range: [7, 21],
        span: [7, 22],
      },
      {
        type: "StringLiteral",
        range: [7, 17],
        span: [7, 18],
      },
      {
        type: "SankeyIdentifier",
        range: [18, 19],
        span: [19, 20],
      },
      {
        type: "SankeyLiteral",
        range: [20, 21],
        span: [21, 22],
      },
    ],
    tokenSpans: [
      {
        index: 2,
        span: [15, 18],
      },
      {
        index: 3,
        span: [18, 19],
      },
      {
        index: 4,
        span: [19, 20],
      },
      {
        index: 5,
        span: [20, 21],
      },
      {
        index: 6,
        span: [21, 22],
      },
    ],
    value: "a\n b",
    raw: '"a\n%% c\n b"',
    negative: [16, 18],
    expected: {
      where: "StringLiteral at 7-18",
      message:
        'the texts of its tokens joined are not its written text: "a\\nb", not "a\\n b"',
    },
  },
] as const)(
  "reports omitted read whitespace after a comment in $case",
  (theCase) => {
    const recorded = recordedTree(theCase.diagram, theCase.fixture)
    const input = theCase.input
    const tree = copyOf(recorded.tree)
    const valueNode = nodesOf(tree).find(
      (node) =>
        node.type === theCase.nodeType &&
        node.range[0] === theCase.nodeRange[0] &&
        node.range[1] === theCase.nodeRange[1],
    )!
    const patches = theCase.nodeSpans.map((patch) => ({
      patch,
      node: nodesOf(tree).find(
        (node) =>
          node.type === patch.type &&
          node.range[0] === patch.range[0] &&
          node.range[1] === patch.range[1],
      )!,
    }))
    for (const { patch, node } of patches)
      span(input, node, patch.span[0], patch.span[1])
    for (const patch of theCase.tokenSpans)
      extendToken(input, tree.tokens[patch.index], patch.span[0], patch.span[1])
    setField(valueNode, "value", theCase.value)
    if (theCase.raw !== null) setField(valueNode, "raw", theCase.raw)
    // packages/parser/docs/tokens.md, Comment regions in tokens: a right
    // fragment includes the space after the region when the unit reads it.
    // The region, node, and written value stay complete in the broken tree.
    expect(checkTree(input, tree)).toEqual([])
    const broken = copyOf(tree)
    extendToken(
      input,
      broken.tokens[theCase.index],
      theCase.negative[0],
      theCase.negative[1],
    )
    expect(checkTree(input, broken)).toContainEqual(theCase.expected)
  },
)

